/* SI psychrometric equations: ASHRAE 2017 Fundamentals ch.1. */
function psySat(t){const T=t+273.15;return Math.exp(t<=.01?-5674.5359/T+6.3925247-.009677843*T+.00000062215701*T*T+2.0747825e-9*T**3-9.484024e-13*T**4+4.1635019*Math.log(T):-5800.2206/T+1.3914993-.048640239*T+.000041764768*T*T-1.4452093e-8*T**3+6.5459673*Math.log(T));}
function psyWs(t,p){const v=psySat(t);return .621945*v/(p-v);}
function psyWwet(t,wb,p){const w=psyWs(wb,p);return wb>=0?((2501-2.326*wb)*w-1.006*(t-wb))/(2501+1.86*t-4.186*wb):((2830-.24*wb)*w-1.006*(t-wb))/(2830+1.86*t-2.1*wb);}
function psyState(t,kind,value,p){if(![t,value,p].every(Number.isFinite)||t< -20||t>60||p<60000||p>110000)throw Error('range');let w;
if(kind==='rh'){if(value<0||value>100)throw Error('range');const pv=psySat(t)*value/100;w=.621945*pv/(p-pv);}else if(kind==='wb'){if(value< -100||value>t)throw Error('range');w=psyWwet(t,value,p);}else if(kind==='dp'){if(value< -100||value>t)throw Error('range');w=psyWs(value,p);}else if(kind==='w')w=value/1000;else if(kind==='h')w=(value-1.006*t)/(2501+1.86*t);else throw Error('range');if(w< -1e-10||w>psyWs(t,p)+1e-9)throw Error('saturation');w=Math.max(0,w);const pv=p*w/(.621945+w),rh=pv/psySat(t)*100;let dp=null;if(pv>psySat(-100)){let lo=-100,hi=t;for(let i=0;i<70;i++){const mid=(lo+hi)/2;if(psySat(mid)<pv)lo=mid;else hi=mid;}dp=(lo+hi)/2;}let lo=-100,hi=t;for(let i=0;i<70;i++){const mid=(lo+hi)/2;if(psyWwet(t,mid,p)<w)lo=mid;else hi=mid;}const wb=(lo+hi)/2,h=1.006*t+w*(2501+1.86*t),v=.287042*(t+273.15)*(1+1.607858*w)/(p/1000);return{t,w,rh,dp,wb,h,v,rho:(1+w)/v,pv,p};}
function psyMix(a,b,f){const w=f*a.w+(1-f)*b.w,h=f*a.h+(1-f)*b.h,t=(h-2501*w)/(1.006+1.86*w);return psyState(t,'w',w*1000,a.p);}
if(typeof module!=='undefined')module.exports={psySat,psyWs,psyWwet,psyState,psyMix};
